#!/usr/bin/env python3
"""Génère les notes IA (/5) + observations IA pour chaque cas d'usage, à partir
des preuves statiques collectées (_evidence.json, _endpoints.json) et de
vérifications réseau réelles, puis écrit un JSON de travail (_notes_ia.json).

Règle de notation appliquée (barème du cahier de recette) :
  4 = conforme, vérifié sur pièces (code + routes + tests) ET au moins une
      vérification réelle exécutée (HTTP public, parité de catalogues, etc.)
  3 = fonctionne partiellement : implémentation + tests présents, mais le
      critère d'exécution runtime n'est pas vérifiable (backend 503 / web 402)
  2 = défaillance fonctionnelle sur un critère majeur constatée sur pièces
      (endpoint documenté absent, aucune implémentation desktop, etc.)
  1 = bloqué : aucune implémentation trouvée
  0 = impossible à exécuter (prérequis absents) — non utilisé ici : le dépôt
      fournit toujours des pièces vérifiables.
"""
import json
from pathlib import Path

HERE = Path(__file__).resolve().parent
ev = {r["id"]: r for r in json.loads((HERE / "_evidence.json").read_text(encoding="utf-8"))}
ep = {r["id"]: r for r in json.loads((HERE / "_endpoints.json").read_text(encoding="utf-8"))}

