# Barème appliqué strictement :
#   4 = une vérification RÉELLEMENT exécutée a confirmé le comportement
#       (appel HTTP mesuré, parité de catalogues calculée, volumétrie mesurée) ;
#   3 = implémentation + tests présents, mais le critère d'exécution runtime
#       n'est pas vérifiable (API 503 / web 402) -> « critère non vérifiable » ;
#   2 = défaillance fonctionnelle majeure constatée sur pièces.
# Un cas « vérifié sur pièces » ne peut donc PAS recevoir 4 : la conformité
# n'est pas démontrée, seulement l'existence du code et des tests.
EXECUTED_MARKERS = ("Vérifié réellement", "mesuré", "parité mesurée", "volumétrie mesurée")

out = {}
for uc_id, ev_row in ev.items():
    if uc_id in SPECIFIC:
        note, obs = SPECIFIC[uc_id]
    else:
        note, obs = "3", "Vérifié sur pièces uniquement."
    if note == "4" and not any(mk in obs for mk in EXECUTED_MARKERS):
        note = "3"
        obs = obs.replace("Note 4 = conforme sur pièces", "Note 3 = critère d'exécution non vérifiable")
        obs = obs.replace("Note 4 = conforme sur pièces + ", "Note 3 = ")
    out[uc_id] = {"note_ia": note, "obs_ia": obs}

(HERE / "_notes_ia.json").write_text(json.dumps(out, ensure_ascii=False, indent=1), encoding="utf-8")

from collections import Counter
c = Counter(v["note_ia"] for v in out.values())
print("cas:", len(out), "| distribution:", dict(sorted(c.items())))
missing = [k for k in ev if k not in SPECIFIC]
print("sans observation spécifique:", missing)
